window.DOSIK=window.DOSIK||{};DOSIK["reg_individuals"]={"1":[{"t":"vs","title":"Gross income: inclusions and exclusions","cols":[{"name":"Included in gross income","items":["Under section 61(a), gross income means all income from whatever source derived, · including compensation for services, · gains derived from dealings in property, interest, and dividends","Under section 72(a)(1), gross income includes any amount received as an annuity · under an annuity, endowment, or life insurance contract, · except as otherwise provided in the chapter","Under section 707(c), a payment to a partner for services, · determined without regard to partnership income, · is treated as made to a person who is not a partner for purposes of section 61(a)","Under section 102(c)(1), amounts transferred by or for an employer · to, or for the benefit of, an employee · are not excluded from gross income as a gift"]},{"name":"Excluded from gross income","items":["Under section 104(a), gross income does not include damages received · on account of personal physical injuries or physical sickness, · other than punitive damages","Under section 103(a), gross income does not include interest on any state or local bond, · except as provided in section 103(b)","Under section 102(a), gross income does not include the value of property · acquired by gift, bequest, devise, or inheritance"]}]},{"t":"table","title":"Gain and holding period","head":["Section","Rule"],"rows":[["Section 1001(a)","The gain from the sale or other disposition of property is the excess of the amount realized over the adjusted basis · provided in section 1011"],["Section 1222(3)","A gain from the sale or exchange of a capital asset held for more than one year is a long-term capital gain"],["Section 1223(9)","A person acquiring property from a decedent whose basis is determined under section 1014 · is considered to have held the property for more than one year · if it is sold within one year after the decedent's death"]]},{"t":"table","title":"Basis of property acquired by gift or from a decedent","head":["Section","Rule"],"rows":[["Section 1015(a)","The basis of property acquired by gift is generally the same as it would be in the hands of the donor, · except that for determining loss, the basis may not exceed the property's fair market value at the time of the gift"],["Section 1014(a)(1)","The basis of property acquired from a decedent is generally its fair market value at the date of the decedent's death"]]}],"2":[{"t":"table","title":"Partnership items","head":["Section","Rule"],"rows":[["Section 702(a)","Each partner must take into account separately the partner's distributive share of items · such as capital gains and losses, charitable contributions, and other separately stated items"],["Section 702(b)","The character of an item in a partner's distributive share is determined as if the item were realized directly · from the source from which the partnership realized it"]]},{"t":"table","title":"S corporation items","head":["Section","Rule"],"rows":[["Section 1366(a)(1)","An S corporation shareholder takes into account a pro rata share of · the corporation's separately stated items and nonseparately computed income or loss · for the shareholder's taxable year in which the corporation's taxable year ends"],["Section 1366(d)(1)","The aggregate losses and deductions a shareholder may take into account cannot exceed the sum of · the shareholder's adjusted basis in the S corporation's stock · and the shareholder's adjusted basis in any indebtedness of the corporation to the shareholder"]]}],"3":[{"t":"table","title":"Adjustments to AGI","head":["Section","Rule"],"rows":[["Section 219(a)","An individual is allowed a deduction equal to the amount of the qualified retirement contributions · of the individual for the taxable year"],["Section 219(b)(1)","The deduction for IRA contributions cannot exceed the lesser of the deductible amount · or the compensation includible in the individual's gross income for the taxable year"],["Section 223(a)","An eligible individual may deduct amounts paid in cash during the taxable year · to a health savings account of such individual"],["Section 223(d)(1)(A)","No contribution will be accepted into a health savings account unless it is in cash, with limited exceptions"],["Section 164(f)(1)","An individual is allowed a deduction for one-half of the taxes imposed by section 1401 · (other than the tax imposed by section 1401(b)(2)) for the taxable year"]]},{"t":"table","title":"Itemized deductions","head":["Section","Rule"],"rows":[["Section 213(a)","Medical expenses paid for the taxpayer, spouse, or a dependent are deductible · only to the extent such expenses exceed 7.5 percent of adjusted gross income"],["Section 163(h)(1)","No deduction is allowed for personal interest paid or accrued by a taxpayer other than a corporation, · subject to specified exceptions such as qualified residence interest"],["Section 163(h)(3)(A)","Qualified residence interest includes interest on acquisition indebtedness and home equity indebtedness · with respect to a qualified residence of the taxpayer, subject to specified limitations"],["Sections 164(a), 164(b)(6)","State and local real property taxes, personal property taxes, and income taxes are allowed as an itemized deduction, · subject to an aggregate dollar limitation for taxable years 2018 through 2025"]]},{"t":"table","title":"Qualified business income deduction","head":["Section","Rule"],"rows":[["Section 199A(a)","A taxpayer other than a corporation may generally deduct an amount equal to the lesser of · the combined qualified business income amount or 20 percent of taxable income in excess of net capital gain"],["Section 199A(c)(1)","Qualified business income is the net amount of qualified items of income, gain, deduction, and loss · with respect to a qualified trade or business of the taxpayer"],["Section 199A(d)(1)(B)","The trade or business of performing services as an employee is not a qualified trade or business · for purposes of the deduction"]]}],"4":[{"t":"table","title":"Capital loss limitations","head":["Section","Rule"],"rows":[["Section 1211(b)","For a taxpayer other than a corporation, capital losses are allowed only to the extent of capital gains, · plus the lower of $3,000 (or $1,500 for a married individual filing a separate return) · or the excess of such losses over such gains"],["Section 1212(b)(1)(A)","The excess of a noncorporate taxpayer's net short-term capital loss · over the net long-term capital gain for a taxable year · is treated as a short-term capital loss in the succeeding taxable year"],["Section 1212(b)(1)(B)","The excess of a noncorporate taxpayer's net long-term capital loss · over the net short-term capital gain for a taxable year · is treated as a long-term capital loss in the succeeding taxable year"],["Section 1212(a)(1)(A)","A corporation may carry back a net capital loss to each of the 3 taxable years preceding the loss year, · subject to specified limitations"]]},{"t":"table","title":"Passive activity and entity loss limitations","head":["Section","Rule"],"rows":[["Section 469(a)(1)","The passive activity loss for the taxable year is not allowed as a deduction · for individuals, estates, trusts, closely held C corporations, and personal service corporations"],["Section 469(c)(1)","A passive activity is a trade or business activity in which the taxpayer does not materially participate"],["Section 469(h)(1)","A taxpayer is treated as materially participating in an activity only if involved in its operations · on a basis that is regular, continuous, and substantial"],["Section 704(d)(1)","A partner's distributive share of partnership loss (including capital loss) is allowed only to the extent of · the adjusted basis of the partner's interest in the partnership · at the end of the partnership year in which such loss occurred"],["Section 1366(d)(1)","An S corporation shareholder's losses are limited to the sum of · the shareholder's adjusted basis in the corporation's stock · and the shareholder's adjusted basis in any indebtedness of the corporation to the shareholder"]]},{"t":"table","title":"Hobby losses and wash sales","head":["Section","Rule"],"rows":[["Section 183(a)","If an activity engaged in by an individual is not engaged in for profit, · no deduction attributable to such activity is allowed except as provided in section 183"],["Section 183(d)","If the gross income from an activity exceeds the deductions attributable to it · for 3 or more of the 5 consecutive taxable years ending with the taxable year, · the activity is presumed, absent contrary IRS determination, to be engaged in for profit"],["Section 1091(a)","No deduction is allowed for a loss on the sale of stock or securities · if, within a period beginning 30 days before and ending 30 days after the sale, · the taxpayer acquires substantially identical stock or securities,"],["Section 1091(a) exception","unless the taxpayer is a dealer acting in the ordinary course of business"]]}],"5":[{"t":"table","title":"Filing status","head":["Section","Rule"],"rows":[["Section 1(a)","A married individual, as defined in section 7703, who makes a joint return with a spouse under section 6013 · is taxed under the rate schedule for married individuals filing jointly and surviving spouses"],["Section 1(a) joint return","A married couple who files a joint return under section 6013 is taxed under section 1(a) · using the rate schedule for married individuals filing jointly and surviving spouses"],["Section 2(b)(1)","An individual generally qualifies as head of household · if not married at the close of the taxable year and maintains a household · that is the principal place of abode of a qualifying child or other dependent for more than half the taxable year"],["Section 2(b)(1) schedule","An unmarried individual who is not a surviving spouse and maintains a household · that is the principal place of abode of a qualifying child for more than half the year · may compute tax under the head of household schedule described in section 1(b)"],["Section 7703(b)","A married individual who lives apart from a spouse for the last 6 months of the taxable year, · maintains as the individual's home a household · that is the principal place of abode of a qualifying child for more than half the year,"],["Section 7703(b) costs","and furnishes over half the cost of maintaining that household, may be treated as not married"]]},{"t":"table","title":"Surviving spouse and joint return","head":["Section","Rule"],"rows":[["Section 7703(a)(1)","An individual whose spouse died during the current taxable year and who has not remarried · is treated as married as of the date of death for that taxable year, permitting a joint return"],["Section 2(a)(2)(A)","A taxpayer who has remarried at any time before the close of the taxable year · shall not be considered a surviving spouse for that year"]]},{"t":"table","title":"Dependents","head":["Section","Rule"],"rows":[["Section 152(a)","The term dependent means a qualifying child or a qualifying relative"],["Section 152(c)(1)(B)","A qualifying child must have the same principal place of abode as the taxpayer for more than one-half of the taxable year"],["Section 152(d)(1)(B)","A qualifying relative's gross income for the calendar year in which the taxpayer's taxable year begins · must be less than the exemption amount defined in section 151(d)"],["Section 152(d)(2)(H)","An individual who has the same principal place of abode as the taxpayer · and is a member of the taxpayer's household for the taxable year · may satisfy the relationship test for a qualifying relative"],["Section 152(e)(1)-(2)","A child of divorced or separated parents may be treated as the qualifying child or qualifying relative · of the noncustodial parent if the custodial parent signs a written declaration · releasing the claim to the exemption for the year"]]}],"6":[{"t":"table","title":"Estimated tax","head":["Section","Rule"],"rows":[["Section 6654(d)(1)(B)","The required annual payment is the lesser of 90 percent of the tax shown on the return for the taxable year · or 100 percent of the tax shown on the return for the preceding taxable year · (subject to a higher percentage for certain higher-income taxpayers)"],["Section 6654(d)(1)(C)(i)","If the adjusted gross income shown on the individual's return for the preceding taxable year exceeds $150,000, · the 100 percent prior-year safe harbor percentage is increased to 110 percent"],["Section 6654(c)(1)","There are 4 required installments of estimated tax for each taxable year"],["Section 6654(e)(1)","No addition to tax is imposed if the tax shown on the return for the taxable year, · reduced by the credit allowable under section 31, is less than $1,000"],["Section 6654(e)(2)","No addition to tax is imposed if the individual had no tax liability for the preceding taxable year, · that year was a taxable year of 12 months, · and the individual was a citizen or resident of the United States throughout that year"]]},{"t":"table","title":"Tax computation and net investment income tax","head":["Section","Rule"],"rows":[["Section 1(a) through 1(d)","An individual's federal income tax liability before credits is computed · by applying the rate schedule that corresponds to the individual's filing status to taxable income"],["Section 1411(a)(1)","An individual is subject to a tax equal to 3.8 percent of the lesser of net investment income for the taxable year · or the excess of modified adjusted gross income over the threshold amount"],["Section 1411(b)","The threshold amount is $250,000 in the case of a joint return or a surviving spouse, · and $200,000 in the case of an individual not otherwise specified"],["Section 1411(c)(1)","Net investment income includes gross income from interest, dividends, annuities, royalties, and rents · (other than such income derived in the ordinary course of certain active trades or businesses), · reduced by properly allocable deductions"],["Section 1411(e)(1)","The tax imposed by section 1411 does not apply to a nonresident alien"]]}]};
